head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");


// 20250207 반영 ELW시장팀+ETN시장팀 = 구조화증권시장팀(2B40), 당번그룹코드(14), ETN,ELW법인제출(15), 업무마감(3D)
// 20250509 ETF, PF 법인제출(18) 생성 및 PF(상장형 수익증권) 체크로직 추가
// 업무마감관리
scwin.vScrenID = 'ULDSTF45000.xml';
scwin.gNowDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
// 당번그룹구분 코드 = 유가 공시팀(11), 유가 시장팀(12), 유가 ETF시장팀(13), 
// 유가 ETN시장팀(14) = 구조화증권 시장팀 , 유가 ELW시장팀(15) 사용안함  20250207, 
// 코스닥 공시팀 : 21, 코스닥 시장팀 : 22, 예방감시팀(유가) : 32, 예방감시팀(코스닥) : 31, 복합시장감시팀(ELW) : 33, 예방감시팀(코넥스) : 34, 예방감시팀(배출권) : 35, 채권 상장팀 : 41, 코넥스 공시팀 : 61, 코넥스 시장팀 : 62
scwin.gDudyTp;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gSecuGrpID;
scwin.gStep1;
scwin.gStep2;
scwin.gStep3;
scwin.gStep4;
scwin.gStatSelf;
scwin.gStep2Tm;
scwin.gStep3Tm;
scwin.gStep4Tm;
scwin.gStatSelfTm;
scwin.gReopenTp; // 법인제출 재개시구분: 22=제출 만 재개시, 23= 제출 및 업무 재개시,  24:제출 만 재개시

scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.DTEC_DD = scwin.vCurDate.substr(0, 6);
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    scwin.gDudyTp = js_gduty;
    //alert(gDudyTp);

};
scwin.fn_getMsg = function() {
    $c.stf.showObj(pnl_step_1, false);
    $c.stf.showObj(pnl_step_2, false);
    $c.stf.showObj(pnl_step_3, false);
    $c.stf.showObj(pnl_step_4, false);
    $c.stf.showObj(txb_cls_tm2_1, false);
    scwin.gNowDate = dts_CloseStatus.getCellData(1, 'NOW');
    scwin.gStep1 = dts_CloseStatus.getCellData(1, 'STEP_1');
    scwin.gStep2 = dts_CloseStatus.getCellData(1, 'STEP_2');
    scwin.gStep3 = dts_CloseStatus.getCellData(1, 'STEP_3');
    scwin.gStep4 = dts_CloseStatus.getCellData(1, 'STEP_4');
    scwin.gStatSelf = dts_CloseStatus.getCellData(1, 'STAT_SELF');
    scwin.gStep2Tm = dts_CloseStatus.getCellData(1, 'STEP_2_TM');
    scwin.gStep3Tm = dts_CloseStatus.getCellData(1, 'STEP_3_TM');
    scwin.gStep4Tm = dts_CloseStatus.getCellData(1, 'STEP_4_TM');
    scwin.gStatSelfTm = dts_CloseStatus.getCellData(1, 'STEP_SELF_TM');
    $c.stf.setObjectValue(txb_cls_tm2, " ■ 제출 마감시각 : " + scwin.gStep2Tm);
    $c.stf.setObjectValue(txb_cls_tm3, " ■ 금감원 마감시각 : " + scwin.gStep3Tm);
    $c.stf.setObjectValue(txb_cls_tmself, " ■ 업무 마감시각 : " + scwin.gStatSelfTm);
    $c.stf.setObjectValue(txb_cls_tm4, " ■ 최종 마감시각 : " + scwin.gStep4Tm);

    // 현시각(시분)
    var vNowMMDD = scwin.gNowDate.substr(11, 2) + scwin.gNowDate.substr(14, 2);


    //alert(gStep1 + gStep2  + gStep3 + gStep4 );
    if ((scwin.gStep1 + scwin.gStep2 + scwin.gStep3 + scwin.gStep4) > 0) {
        $c.stf.setObjectValue(txb_msg, "");
        if (scwin.gStep1 == 1) {
            if (scwin.gStep4 == 2) {
                // 18:00 이전에 비정상적으로 최종업무 마감이 된 상태이면...
                img_step4.src = "../img/step_bg04_c.gif";
                $c.stf.showObj(pnl_step_4, true);
                $c.stf.setObjectValue(txb_now4, "마감시각 : " + scwin.gStep4Tm);
                $c.stf.setObjectValue(txa_step_4, $c.stf.getMessageParam("MSG-0905", ""));
            } else {
                img_step1.src = "../img/step_bg01_c.gif";
                $c.stf.showObj(pnl_step_1, true);
                $c.stf.setObjectValue(txb_now1, "현재시각 : " + scwin.gNowDate);
                $c.stf.setObjectValue(txa_step_1, $c.stf.getMessageParam("MSG-0901", ""));
            }
        }
        if (scwin.gStep2 == 1) {
            // 법인제출 마감 안 된상태

            img_step2.src = "../img/step_bg02_c.gif";
            $c.stf.showObj(pnl_step_2, true);
            $c.stf.setObjectValue(txb_now2, "현재시각 : " + scwin.gNowDate);
            //setObjectValue(txa_step_2,  getMessageParam("MSG-0902", ""));
            $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0906", ""));
            if (scwin.gDudyTp == "12" || scwin.gDudyTp == "22" || scwin.gDudyTp == "62" ||
                scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음.  코넥스 예방감시팀(34) 추가 by 20130625 예방감시(배출권)추가 20150306
                $c.stf.showObj(img_submit_reopen2, false); //법인제출재개시 버튼
                $c.stf.showObj(img_submit_close2, false); //법인제출마감 버튼


                if (scwin.gStatSelf == 1) {
                    // 해당부서 마감이 안되어있을경우	
                    if (vNowMMDD >= "1600" &&
                        (scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35")) {
                        $c.stf.showObj(img_biz_close2, true); // 시장감시부 는  16시 이후 업무마감할 수 있다.

                    }
                } else {
                    $c.stf.showObj(img_biz_close2, false);
                    $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0913", ""));
                }
            } else {
                $c.stf.showObj(img_submit_reopen2, false);
                $c.stf.showObj(img_submit_close2, true);
                $c.stf.showObj(img_biz_close2, false);
            }
        } else if (scwin.gStep2 == 2) {
            // 법인제출 마감된 상태

            img_step2.src = "../img/step_bg02_c.gif";
            $c.stf.showObj(pnl_step_2, true);
            $c.stf.setObjectValue(txb_now2, "마감시각 : " + scwin.gStep2Tm);
            $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0902", ""));
            if (scwin.gDudyTp == "12" || scwin.gDudyTp == "22" || scwin.gDudyTp == "62" ||
                scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음. *추가 20080829 유명현 상장심사2팀도 해당함.
                $c.stf.showObj(img_submit_reopen2, false);
                $c.stf.showObj(img_submit_close2, false);
                if (scwin.gStatSelf == 1) {
                    // 해당부서 마감이 안되어있을경우					         
                    if (vNowMMDD >= "1600" && (scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35")) {
                        $c.stf.showObj(img_biz_close2, true); // 시장감시부 는  16시 이후 업무마감할 수 있다.

                    }
                } else {
                    $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0912", ""));
                    $c.stf.showObj(img_biz_close2, false);
                }
            } else {
                // 법인제출 재개시할때 23시이전여부체크
                if (vNowMMDD < '2300') {
                    //코스닥공시부 법인재출 재개시시 당번팀장, 부서장만 가능하도록 변경 SrM-000262928 20240419
                    if (scwin.gDudyTp == "21") {
                        if (scwin.gDutyChrg == 'Y' || scwin.gJobTitle == '40') {
                            $c.stf.showObj(img_submit_reopen2, true);
                        } else {
                            $c.stf.showObj(img_submit_reopen2, false);
                        }
                    } else {
                        $c.stf.showObj(img_submit_reopen2, true);
                    }
                } else {
                    $c.stf.showObj(img_submit_reopen2, false);
                }
                $c.stf.showObj(img_submit_close2, false);
                if (scwin.gDudyTp == "13" || scwin.gDudyTp == "14" || scwin.gDudyTp == "16") {
                    // ETN시장팀(14), 신종증권(16)은 금감원과 관계없이 업무마감 버튼 생성, ELW시장팀(15) 삭제
                    //ETF시장팀(13) 추가 20250509
                    if (scwin.gStatSelf == 1) {
                        // 해당부서 마감이 안되어있을경우	
                        $c.stf.showObj(img_biz_close2, true);
                    } else {
                        $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0912", ""));
                        $c.stf.showObj(img_biz_close2, false);
                        $c.stf.showObj(img_submit_reopen2, false);
                    }
                } else {
                    $c.stf.showObj(img_biz_close2, false);
                }
            }
        } else {
            if (scwin.gStep3 != 1 && scwin.gStep3 != 2 && scwin.gStep4 != 1) {
                // 시장감시부 는  16시 이후 업무마감할 수 있다. : 2009.02.09 수정 처리
                if (vNowMMDD >= "1600" && (scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35")) {
                    $c.stf.showObj(pnl_step_2, true);
                    $c.stf.setObjectValue(txb_now2, "현재시각 : " + scwin.gNowDate);
                    $c.stf.showObj(img_submit_reopen2, false);
                    $c.stf.showObj(img_submit_close2, false);
                    $c.stf.showObj(img_biz_close2, false);
                    if (scwin.gStatSelf == "1") {
                        // 해당부서 마감이 안되어있을경우						
                        $c.stf.showObj(img_biz_close2, true);
                    } else {
                        $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0913", ""));
                        $c.stf.showObj(img_biz_close2, false);
                    }
                }
            }
        }

        // 제출마감 된 상태 & 업무마감 안 된상태
        if (scwin.gStep3 == 1) {
            img_step3.src = "../img/step_bg03_c.gif";
            $c.stf.showObj(pnl_step_3, true);
            $c.stf.setObjectValue(txb_now3, "현재시각 : " + scwin.gNowDate);
            $c.stf.setObjectValue(txa_step_3, $c.stf.getMessageParam("MSG-0903", ""));
            if (scwin.gDudyTp == "12" || scwin.gDudyTp == "22" || scwin.gDudyTp == "62" ||
                scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음.
                $c.stf.showObj(img_submit_reopen3, false);
            } else {
                // 법인제출 재개시할때 23시이전여부체크
                if (vNowMMDD < '2300') {
                    scwin.gReopenTp = '24';
                    //코스닥공시부 법인재출 재개시시 당번팀장, 부서장만 가능하도록 변경 SrM-000262928 2024712
                    if (scwin.gDudyTp == "21") {
                        if (scwin.gDutyChrg == 'Y' || scwin.gJobTitle == '40') {
                            $c.stf.showObj(img_submit_reopen3, true);
                        } else {
                            $c.stf.showObj(img_submit_reopen3, false);
                        }
                    } else {
                        $c.stf.showObj(img_submit_reopen3, true);
                    }
                } else {
                    $c.stf.showObj(img_submit_reopen3, false);
                }
            }
            if (scwin.gStatSelf == 1) {
                // 당번소속그룹 마감이 안되어있을경우
                $c.stf.showObj(img_biz_close3, true);
            } else {
                $c.stf.showObj(img_biz_close3, false);
            }
        } else if (scwin.gStep3 == 2) {
            // 당번소속그룹의 마감은 완료 & 최종마감이 안된 상태				
            img_step3.src = "../img/step_bg03_c.gif";
            $c.stf.showObj(pnl_step_3, true);
            $c.stf.setObjectValue(txb_now3, "현재시각 : " + scwin.gNowDate);
            $c.stf.setObjectValue(txa_step_3, $c.stf.getMessageParam("MSG-0904", ""));
            if (scwin.gDudyTp == "12" || scwin.gDudyTp == "22" || scwin.gDudyTp == "62" ||
                scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35") {
                // 유/코시장운영팀, 시장감시부 는 법인제출 마감 권한 없음.
                $c.stf.showObj(img_submit_reopen3, false);
            } else {
                // 법인제출 재개시할때 23시이전여부체크
                if (vNowMMDD < '2300') {
                    scwin.gReopenTp = '23';
                    $c.stf.showObj(img_submit_reopen3, false);
                } else {
                    $c.stf.showObj(img_submit_reopen3, false);
                }
            }
            $c.stf.showObj(img_biz_close3, false);
        }
        if (scwin.gStep4 == 1) {
            img_step4.src = "../img/step_bg04_c.gif";
            $c.stf.showObj(pnl_step_4, true);
            $c.stf.setObjectValue(txb_now4, "마감시각 : " + scwin.gStep4Tm);
            $c.stf.setObjectValue(txa_step_4, $c.stf.getMessageParam("MSG-0905", ""));
        }
    } else {
        //alert("업무가 개시되지 않았습니다. ");
        $c.stf.setObjectValue(txb_msg, "알림 : 업무가 개시되지 않았습니다.");
    }

    // 당번그룹코드가 없는 사용자 로그인되면 처리버튼 모두 hidden 처리
    if (scwin.gDudyTp == "") {
        $c.stf.showObj(img_submit_close2, false);
        $c.stf.showObj(img_submit_reopen2, false);
        $c.stf.showObj(img_biz_close2, false);
        $c.stf.showObj(img_submit_reopen3, false);
        $c.stf.showObj(img_biz_close3, false);
        $c.stf.showObj(txb_cls_tmself, false);
        $c.stf.showObj(txb_cls_tm2_1, true);
        $c.stf.setObjectValue(txb_cls_tm2, " ■ (유) 제출 마감시각 : " + dts_CloseStatus.getCellData(1, 'STEP_11_TM'));
        $c.stf.setObjectValue(txb_cls_tm2_1, " ■ (코) 제출 마감시각 : " + dts_CloseStatus.getCellData(1, 'STEP_12_TM'));
    }
};




// 화면 로딩시 디폴트 검색
scwin.fn_Search = function(pReload) {
    var url = "/BizCloseMgt.do?method=readCloseStatus&inputMessageId=CLOSESTATCOND_IN" + "&outputMessageId=CLOSESTAT_OUT" + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&DUTY_GRP_TP=" + scwin.gDudyTp;
    if (pReload != 'Y') {
        //자동refresh일때는 로그 없앰
        url = url + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }
    dts_CloseStatus.DataID = encodeURI(url);
    dts_CloseStatus.reset();
};


// 화면 로딩시 디폴트 검색
scwin.fn_InitSearch = function() {
    scwin.fn_Reload('N');
};
scwin.fn_Reload = function(pReload) {
    scwin.fn_Search(pReload);
    setTimeout("fn_Reload('Y')", 60000); // 1초 = 1000 , 60초 = 60000		

};


/*
   마감 및 재개시 처리
   - 1 : 법인 제출 마감 
   - 2 : 법인제출 재개시, 23=제출 및 업무재개시, 24=제출만 재개시
   - 3 :  업무 마감
 */
scwin.fn_CloseProcess = function(pCloseStep) {
    //alert(gLdMktTp +","+ js_duty);

    /**
    * 당번 공용아이디 제거하면서 마감은 팀전체가 할 수 있게 수정한다. (2011.06 P.H.J)
    if(js_jobtitl == '09' || js_jobtitl == '06') {	// 팀장이나 부서장일때

    	if( js_duty_chrg == 'N'  || js_duty_chrg == '') {
    	//if(gLdMktTp == '9' && ( js_duty == 'N'  || js_duty == '')) {
    	//if(gLdMktTp == '9' ) {
    	//if(js_id !='001084' && js_id !='880912' && js_id !='010817' && js_id !='990540'  ) {	// 임시테스트용
    		alert("마감처리 권한이 없습니다.");
    		return;
    	}		
    } else {
    	if( js_duty == 'N'  || js_duty == '') {
    	//if(gLdMktTp == '9' && ( js_duty == 'N'  || js_duty == '')) {
    	//if(gLdMktTp == '9' ) {
    	//if(js_id !='001084' && js_id !='880912' && js_id !='010817' && js_id !='990540'  ) {	// 임시테스트용
    		alert("마감처리 권한이 없습니다.");
    		return;
    	}	
    }
    */

    dts_CloseProcs.removeAll();
    dts_CloseProcs.insertRow();
    dts_CloseProcs.setCellData(1, "DUTY_GRP_TP", scwin.gDudyTp);
    dts_CloseProcs.setCellData(1, "LD_MKT_TP", scwin.gLdMktTp);
    dts_CloseProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_CloseProcs.setCellData(1, "CLOSE_STEP", pCloseStep);
    var vProcMsg = "";
    if (pCloseStep == 1) {
        vProcMsg = "법인제출 마감";
    } else if (pCloseStep == 22 || pCloseStep == 23 || pCloseStep == 24) {
        vProcMsg = "법인제출 재개시";
    } else if (pCloseStep == 3) {
        vProcMsg = "업무 마감";
    }
    var vAnswer = confirm($c.stf.getMessageParam("MSG-A006", vProcMsg));
    if (vAnswer == true) {
        // 업무마감 처리에서 법인제출마감,법인제출재개시,업무마감 체크  LSH_20160411
        scwin.fn_businessClosingCheck();
    }
};
