//미승인건 처리 fn_GetCount() 
scwin.fn_CheckBizClose = function(vCnt, dep_nm) {
    if (vCnt > 0) {
        $c.win.alert("[" + dep_nm + "]의 " + "미승인된 공시가 " + vCnt + "건 존재합니다. 처리후 마감하세요.");
        return false;
    }

    // 시장조성자 LP 보유량 마감처리 체크(주식시장운영팀(유가), 코스닥시장운영팀) LSH_20160328
    // MMLP시스템으로 이전 되므로 체크 안함 20230120
    /*if (gDudyTp == "12"  || gDudyTp == "22") {
			fn_marketMakerCheck();
			return;
         }
        */
    // 종목 담당자 미지정 체크(유가 공시팀, 코스닥 공시팀, 코넥스상장관리팀, ETF시장팀) LSH_20160912
    if (scwin.gDudyTp == "11" || scwin.gDudyTp == "21" || scwin.gDudyTp == "61") {
        scwin.gSecuGrpID = "ST";
        scwin.fn_isuChrgNDesignCheck(scwin.gSecuGrpID);
        return;
    }
    // ETF, ETN인 경우 투자유의 마감이 됐는지 체크 한다. KBoY 2020-08-07
    else if (scwin.gDudyTp == "13" || scwin.gDudyTp == "14") {
        scwin.isBzClsRelInvstwarn4ETNorETN(); //이 메소드 안에서 13인 경우 fn_isuChrgNDesignCheck() 따로 호출함
        return;
    }
    // ATS 예약공시 체크(주식시장운영팀(유가), 코스닥시장운영팀) 2025.03
    else if (scwin.gDudyTp == "12" || scwin.gDudyTp == "22") {
        scwin.fn_atsDsclReservation();
        return;
    }
    // 시장감시 예약공시 체크(사이버분석팀(유/코/넥/배출권/ELW) 2025.03
    else if (scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35") {
        scwin.fn_atsDsclReservation();
        return;
    } else {
        // 2. 모두 승인일때 업무마감
        scwin.fn_CloseProcess(3);
    }
};




