scwin.fn_getBondMsg = function() {
    $c.stf.showObj(pnl_step_1, false);
    $c.stf.showObj(pnl_step_2, false);
    $c.stf.showObj(pnl_step_3, false);
    $c.stf.showObj(pnl_step_4, false);
    $c.stf.showObj(txb_cls_tm2_1, false);
    scwin.gNowDate = dts_CloseStatus.getCellData(1, 'NOW');
    scwin.gStep1 = dts_CloseStatus.getCellData(1, 'STEP_1');
    scwin.gStep2 = dts_CloseStatus.getCellData(1, 'STEP_2');
    scwin.gStep3 = dts_CloseStatus.getCellData(1, 'STEP_3');
    scwin.gStep4 = dts_CloseStatus.getCellData(1, 'STEP_4');
    scwin.gStatSelf = dts_CloseStatus.getCellData(1, 'STAT_SELF');
    scwin.gStep2Tm = dts_CloseStatus.getCellData(1, 'STEP_2_TM');
    scwin.gStep3Tm = dts_CloseStatus.getCellData(1, 'STEP_3_TM');
    scwin.gStep4Tm = dts_CloseStatus.getCellData(1, 'STEP_4_TM');
    scwin.gStatSelfTm = dts_CloseStatus.getCellData(1, 'STEP_SELF_TM');
    $c.stf.setObjectValue(txb_cls_tm2, " ■ 제출 마감시각 : " + scwin.gStep2Tm);
    $c.stf.setObjectValue(txb_cls_tm3, " ■ 금감원 마감시각 : " + scwin.gStep3Tm);
    $c.stf.setObjectValue(txb_cls_tmself, " ■ 업무 마감시각 : " + scwin.gStatSelfTm);
    $c.stf.setObjectValue(txb_cls_tm4, " ■ 최종 마감시각 : " + scwin.gStep4Tm);

    // 현시각(시분)
    var vNowMMDD = scwin.gNowDate.substr(11, 2) + scwin.gNowDate.substr(14, 2);

    //alert(gStep1 + gStep2  + gStep3 + gStep4 + gStatSelf);

    /*
    gStep1 = '0';
    gStep2 = '0';
    gStep3 = '1';
    gStep4 = '0';
    */

    if ((scwin.gStep1 + scwin.gStep2 + scwin.gStep3 + scwin.gStep4) > 0) {
        $c.stf.setObjectValue(txb_msg, "");
        if (scwin.gStep1 == 1) {
            if (scwin.gStep4 == 2) {
                // 18:00 이전에 비정상적으로 최종업무 마감이 된 상태이면...
                img_step4.src = "../img/step_bg04_c.gif";
                $c.stf.showObj(pnl_step_4, true);
                $c.stf.setObjectValue(txb_now4, "마감시각 : " + scwin.gStep4Tm);
                $c.stf.setObjectValue(txa_step_4, $c.stf.getMessageParam("MSG-0905", ""));
            } else {
                img_step1.src = "../img/step_bg01_c.gif";
                $c.stf.showObj(pnl_step_1, true);
                $c.stf.setObjectValue(txb_now1, "현재시각 : " + scwin.gNowDate);
                $c.stf.setObjectValue(txa_step_1, $c.stf.getMessageParam("MSG-0901", ""));
            }
        }
        if (scwin.gStep2 == 1) {
            // 법인제출 마감 안 된상태

            img_step2.src = "../img/step_bg02_c.gif";
            $c.stf.showObj(pnl_step_2, true);
            $c.stf.setObjectValue(txb_now2, "현재시각 : " + scwin.gNowDate);
            $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0906", ""));
            $c.stf.showObj(img_submit_reopen2, false);
            $c.stf.showObj(img_submit_close2, true);
            $c.stf.showObj(img_biz_close2, false);
        } else if (scwin.gStep2 == 2) {
            // 법인제출 마감된 상태

            img_step2.src = "../img/step_bg02_c.gif";
            $c.stf.showObj(pnl_step_2, true);
            $c.stf.setObjectValue(txb_now2, "마감시각 : " + scwin.gStep2Tm);
            $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0902", ""));

            // 법인제출 재개시할때 23시이전여부체크
            if (vNowMMDD < '2300') {
                $c.stf.showObj(img_submit_reopen2, true);
            } else {
                $c.stf.showObj(img_submit_reopen2, false);
            }
            $c.stf.showObj(img_submit_close2, false);
            $c.stf.showObj(img_biz_close2, false);
            if (scwin.gStatSelf == "1") {
                // 해당부서 마감이 안되어있을경우						

                //showObj(img_biz_close2, true);	//채권상장팀 금감원 마감되지 않아도 마감될수 있도록 요청(심준영차장 2009.11.27적용)

            } else {
                $c.stf.setObjectValue(txa_step_2, $c.stf.getMessageParam("MSG-0912", ""));
                $c.stf.showObj(img_biz_close2, false);
                $c.stf.showObj(img_submit_reopen2, false);
            }
        }

        // 제출마감 된 상태 & 업무마감 안 된상태
        if (scwin.gStep3 == 1) {
            img_step3.src = "../img/step_bg03_c.gif";
            $c.stf.showObj(pnl_step_3, true);
            $c.stf.setObjectValue(txb_now3, "현재시각 : " + scwin.gNowDate);
            $c.stf.setObjectValue(txa_step_3, $c.stf.getMessageParam("MSG-0903", ""));

            // 법인제출 재개시할때 23시이전여부체크
            if (vNowMMDD < '2300') {
                scwin.gReopenTp = '24';
                $c.stf.showObj(img_submit_reopen3, true);
            } else {
                $c.stf.showObj(img_submit_reopen3, false);
            }
            if (scwin.gStatSelf == 1) {
                // 당번소속그룹 마감이 안되어있을경우
                $c.stf.showObj(img_biz_close3, true);
            } else {
                $c.stf.showObj(img_biz_close3, false);
            }
        } else if (scwin.gStep3 == 2) {
            // 당번소속그룹의 마감은 완료 & 최종마감이 안된 상태				
            img_step3.src = "../img/step_bg03_c.gif";
            $c.stf.showObj(pnl_step_3, true);
            $c.stf.setObjectValue(txb_now3, "현재시각 : " + scwin.gNowDate);
            $c.stf.setObjectValue(txa_step_3, $c.stf.getMessageParam("MSG-0904", ""));

            // 법인제출 재개시할때 23시이전여부체크
            if (vNowMMDD < '2300') {
                scwin.gReopenTp = '23';
                $c.stf.showObj(img_submit_reopen3, false);
            } else {
                $c.stf.showObj(img_submit_reopen3, false);
            }
            $c.stf.showObj(img_biz_close3, false);
        }
        if (scwin.gStep4 == 1) {
            img_step4.src = "../img/step_bg04_c.gif";
            $c.stf.showObj(pnl_step_4, true);
            $c.stf.setObjectValue(txb_now4, "마감시각 : " + scwin.gStep4Tm);
            $c.stf.setObjectValue(txa_step_4, $c.stf.getMessageParam("MSG-0905", ""));
        }
    } else {
        //alert("업무가 개시되지 않았습니다. ");
        $c.stf.setObjectValue(txb_msg, "알림 : 업무가 개시되지 않았습니다.");
    }

    // 당번그룹코드가 없는 사용자 로그인되면 처리버튼 모두 hidden 처리
    if (scwin.gDudyTp == "") {
        $c.stf.showObj(img_submit_close2, false);
        $c.stf.showObj(img_submit_reopen2, false);
        $c.stf.showObj(img_biz_close2, false);
        $c.stf.showObj(img_submit_reopen3, false);
        $c.stf.showObj(img_biz_close3, false);
        $c.stf.showObj(txb_cls_tmself, false);
        $c.stf.showObj(txb_cls_tm2_1, true);
        $c.stf.setObjectValue(txb_cls_tm2, " ■ (유) 제출 마감시각 : " + dts_CloseStatus.getCellData(1, 'STEP_11_TM'));
        $c.stf.setObjectValue(txb_cls_tm2_1, " ■ (코) 제출 마감시각 : " + dts_CloseStatus.getCellData(1, 'STEP_12_TM'));
    }
};



