// 업무마감 처리에서 법인제출마감,법인제출재개시,업무마감 체크  LSH_20160411
scwin.fn_businessClosingCheckResult = function(pStat10, pStat30) {
    var vProcsStat = $c.stf.getObjectValue(txb_procs_stat);
    if (pStat30 == 0) {
        $c.win.alert("이미 업무가 마감 되었습니다.");
        scwin.fn_Reload('N');
    } else {
        // 법인제출재개시
        if (vProcsStat == 'img_submit_reopen2') {
            if (pStat10 == 0) {
                //정상처리 			
                scwin.fn_CloseProcessAction();
            } else {
                $c.win.alert("이미 법인 제출이 재개시 되었습니다.");
                scwin.fn_Reload('N');
            }

            // 법인제출마감	

        } else if (vProcsStat == 'img_submit_close2') {
            if (pStat10 > 0) {
                //정상처리 			
                scwin.fn_CloseProcessAction();
            } else {
                $c.win.alert("이미 법인 제출이 마감 되었습니다.");
                scwin.fn_Reload('N');
            }

            // 업무마감		

        } else if (vProcsStat == 'img_biz_close2') {
            if (pStat30 > 0) {
                //정상처리 								
                scwin.fn_CloseProcessAction();
            } else {
                $c.win.alert("이미 업무가 마감 되었습니다.");
                scwin.fn_Reload('N');
            }

            // 법인제출재개시	

        } else if (vProcsStat == 'img_submit_reopen3') {
            if (pStat10 == 0) {
                //정상처리 			
                scwin.fn_CloseProcessAction();
            } else {
                $c.win.alert("이미 법인 제출이 재개시 되었습니다.");
                scwin.fn_Reload('N');
            }

            // 업무마감

        } else if (vProcsStat == 'img_biz_close3') {
            if (scwin.gDudyTp == "12" || scwin.gDudyTp == "22" || scwin.gDudyTp == "62" ||
                scwin.gDudyTp == "31" || scwin.gDudyTp == "32" || scwin.gDudyTp == "33" || scwin.gDudyTp == "34" || scwin.gDudyTp == "35") {
                if (pStat30 > 0) {
                    //정상처리 			
                    scwin.fn_CloseProcessAction();
                } else {
                    $c.win.alert("이미 업무가 마감 되었습니다.");
                    scwin.fn_Reload('N');
                }
            } else {
                if (pStat10 == 0 && pStat30 > 0) {
                    //정상처리 			
                    scwin.fn_CloseProcessAction();
                } else if (pStat10 > 0 && pStat30 > 0) {
                    $c.win.alert("이미 법인 제출이 재개시 되었습니다.");
                    scwin.fn_Reload('N');
                } else {
                    $c.win.alert("이미 업무가 마감 되었습니다.");
                    scwin.fn_Reload('N');
                }
            }
        }
    }
};







