// 상장형수익증권 종목담당자 지정 추가 20250509
scwin.fn_isuChrgNDesignCheckResult = function(cnt) {
    var menu_nm;
    if (scwin.gDudyTp == "11") {
        menu_nm = "공시업무별담당자지정(유)_STF30610";
    } else if (scwin.gDudyTp == "21") {
        menu_nm = "공시업무별담당자지정(코)_STF30611";
    } else if (scwin.gDudyTp == "61") {
        menu_nm = "공시업무별담당자지정(넥)_STF40080";
    } else if (scwin.gDudyTp == "13") {
        if (scwin.gSecuGrpID == "EF") {
            menu_nm = "ETF 종목 담당자 지정_STF30615";
        } else if (scwin.gSecuGrpID == "PF") {
            menu_nm = "상장형수익증권 종목담당자 지정_STF34200";
        }
    } else {
        menu_nm = "공시업무별담당자지정";
    }
    if (cnt == '0') {
        //정상처리 
        //2017-07-12 KBoY (유)공시팀만 시장조치데이터 비교 
        if (scwin.gDudyTp == "11") {
            scwin.isClearMktActData();
        } else if (scwin.gDudyTp == "13") {
            if (scwin.gSecuGrpID == "EF") {
                //상장형 수익증권 상장송수신 마감체크 20250509
                //EF체크로직을 끝내고 PF체크로직 시작
                scwin.fn_pfCloseCheck();
            } else if (scwin.gSecuGrpID == "PF") {
                //투자유의 마감체크로직
                scwin.isBzClsRelInvstwarnPF();
            }
        } else {
            // 업무마감
            scwin.fn_CloseProcess(3);
        }
    } else {
        $c.win.alert("익일 상장 종목의 담당자가 지정되지 않았습니다.\n" + menu_nm + " 화면의\n[미지정회사 담당자지정] 탭에서\n담당자 지정을 해주시기 바랍니다.");
        return false;
    }
};




