    } else {
        mktNm = 'ETN';
        screnID = "STF08310"; //ETN

    }
    var closeYN = dts_invstwrnETFnETN.getCellData(1, 'CHECK_CLOSE');
    if (closeYN == 'N') {
        $c.win.alert(mktNm + " 투자유의 마감처리가 되지 않았습니다.\n투자유의 마감처리 마감처리_" + screnID + " 화면에서\n마감처리를 해주시기 바랍니다.");
    } else {
        if (scwin.gDudyTp == '13') {
            //ETF인 경우만 미지정 종목이 있는지 체크함. fn_CheckBizClose여기서 가져옴.
            scwin.gSecuGrpID = "EF";
            scwin.fn_isuChrgNDesignCheck(scwin.gSecuGrpID);
        } else {
            scwin.fn_CloseProcess(3);
        }
    }
};
scwin.fn_digitalCloseCheck = function() {
    var url = "/BizCloseMgt.do?method=digitalCloseCheck&inputMessageId=DSCLCOUNT_INOUT" + "&outputMessageId=DSCLCOUNT_INOUT";
    dts_digitalCloseCheck.DataID = encodeURI(url);
    dts_digitalCloseCheck.reset();
};
scwin.fn_digitalDelistCloseCheck = function() {
    var url = "/BizCloseMgt.do?method=digitalDelistCheck&inputMessageId=DSCLCOUNT_INOUT" + "&outputMessageId=DSCLCOUNT_INOUT";
    dts_digitalDelistCheck.DataID = encodeURI(url);
    dts_digitalDelistCheck.reset();
};
scwin.fn_CheckDigitalBizClose = function(closeCheck) {
    if (closeCheck == '1') {
        $c.win.alert("디지털증권 신규상장 마감처리가 되지 않았습니다.\n신규상장 마감처리_STF70016 화면에서\n마감처리를 해주시기 바랍니다.");
        return false;
    } else if (closeCheck == '0') {
        //정상처리 
        //만기에 의한 상장폐지 공시 배포여부 체크
        scwin.fn_digitalDelistCloseCheck();
    }
};
scwin.fn_CheckDigitalBizDelist = function(closeCheck) {
    if (closeCheck == '1') {
        if (confirm("디지털증권 만기에 의한 상장폐지 공시가 배포 되지 않았습니다. 진행하시겠습니까?")) {
            scwin.fn_GetCount();
        } else {
            return false;
        }
    } else {
        scwin.fn_GetCount();
    }
};




