scwin.img_biz_close2_onclick = function() {
    $c.stf.setObjectValue(txb_procs_stat, "img_biz_close2");
    if (scwin.gDudyTp == '13') {
        //ETF시장팀 체크 LSH_20160912
        scwin.fn_etfCloseCheck();
    } else if (scwin.gDudyTp == '14') {
        //ETN시장팀 체크 LSH_20160912
        scwin.fn_etnCloseCheck();
    }
    //ELW시장팀 체크_20230127

    //ELW시장팀+ETN시장팀 통합 20250207

    /*else if(gDudyTp == '15') {
		fn_elwCloseCheck();	
	} */
    else if (scwin.gDudyTp == '22' || scwin.gDudyTp == '11') {
        //코스닥 시장운영팀/유가 공시팀 체크 공시일정표에 미확정 목록이 있을시 마감을 못하게 한다.
        scwin.fn_mktOperTeamCloseCheck();
    } else if (scwin.gDudyTp == '32' || scwin.gDudyTp == '31' || scwin.gDudyTp == '34' || scwin.gDudyTp == '35' || scwin.gDudyTp == '33') {
        //예방감시팀(유가,코스닥,코넥스,배출권)의 타시스템 공시가 제출 되지 않았으면 마감을 못하게 한다. LSH_20161017
        //ELW 업무가 사이버감시팀으로 넘어오면서 기존에 없던 타시스템 공시 마감 기능 추가 KBoY_20220224
        scwin.fn_otherSystemDisclsCloseCheck();
    } else if (scwin.gDudyTp == '16') {
        //디지털증권시장팀 체크_20230914
        scwin.fn_digitalCloseCheck();
    } else {
        // 1. 승인안된 공시가 있는지 체크
        scwin.fn_GetCount();
    }
};
